<script>
  import SpkIcon from '../Components/SpkIcon.svelte'
  export let overview = {}
  export let recentSpks = []
  const cards = [
    {key:'customers',label:'Pelanggan terdaftar',icon:'users',href:'/customers'},
    {key:'vehicles',label:'Kendaraan terdaftar',icon:'car',href:'/vehicles'},
    {key:'active',label:'Sedang dikerjakan',icon:'clipboard',href:'/spk?status=in_progress'},
    {key:'unpaid',label:'Invoice belum lunas',icon:'file',href:'/invoices'}
  ]
  const labels = {draft:'Draft',in_progress:'Dikerjakan',completed:'Selesai',cancelled:'Dibatalkan'}
  const currency = value => new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(value)||0)
</script>

